const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');

if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workflowId', 'entityType', 'entityId', 'workspaceId', 'userId', 'callbackUrl'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

if (body.entityType !== 'company') {
  throw new Error('intel-032-strategy requiert entityType="company"');
}

return [{
  json: {
    runId: body.runId,
    workflowId: body.workflowId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    companyId: body.entityId,
    callbackUrl: body.callbackUrl,
  }
}];

const upstream = $('Validate Entity').item.json;
const context = $input.first().json;

// ADR-0012 D-3 — même contrainte que intel-030/intel-031 : le LLM ne peut
// émettre que 3 des 5 valeurs de provenance (relational/folio_legacy/inferred).
// Un offer_match ancré sur un enjeu ouvert + une offre dont use_cases/keywords
// recoupent explicitement le problem_statement est "relational" (fait de
// contexte). Un rapprochement plus spéculatif (aucun recoupement textuel
// direct, déduction du modèle) est "inferred". "folio_legacy" seulement si le
// rapprochement s'appuie sur context.previousPitches/legacyPitches (données
// datées, peu fiables).

const SYSTEM_PROMPT = `Tu construis la "Stratégie commerciale" pour Kredo Digital (ESN premium :
Data/IA, Cloud, Product Management, Cybersécurité) — étape 4 de la chaîne de décision
commerciale (ADR-0012). Tu transformes les enjeux déjà cartographiés (étape 3) en
mapping enjeu↔offre, angles d'approche, messages clés par persona et objections
anticipées. Tu NE rédiges PAS de pitch final ici (ça reste intel-020-communication,
canaux spoken_pitch_30s/meeting_briefing) — cette étape produit la STRATÉGIE (le
mapping et les angles), pas le texte définitif à prononcer.

RÈGLES ABSOLUES :
1. Le CONTEXTE ci-dessous (JSON) est ta SEULE source. context.openIssues liste les
   enjeux déjà ouverts et priorisés (Lot 4) — c'est ton point de départ. Si
   context.openIssues est vide, renvoie offer_matches: [] (n'invente AUCUN enjeu
   ici, ce n'est pas ton rôle).
2. Chaque offer_match référence un issue_id EXACTEMENT présent dans
   context.openIssues et un offer_id EXACTEMENT présent dans context.offersCatalog
   — jamais un id inventé. Un enjeu peut être couvert par 0, 1 ou plusieurs offres ;
   ne force pas un rapprochement faible juste pour "couvrir" un enjeu.
3. Chaque offer_match porte une provenance parmi EXACTEMENT ces 3 valeurs :
   - "relational" : le rapprochement enjeu↔offre s'appuie sur un recoupement
     explicite (mots-clés/cas d'usage de l'offre qui recoupent le problem_statement
     de l'enjeu, ou practices_fit du secteur qui pointe vers cette practice).
   - "folio_legacy" : le rapprochement s'appuie sur context.previousPitches ou
     context.legacyPitches (contenu FOLIO daté, peu fiable).
   - "inferred" : déduction que tu formules toi-même sans recoupement direct.
   N'utilise JAMAIS "human_verified" ni "engine_researched" — valeurs réservées.
4. approach_angles : 2 à 4 angles d'approche commerciale concrets (pas des
   généralités), ancrés sur les enjeux les plus importants/urgents et sur
   context.sectorPlaybook si présent (fenêtres commerciales, échéances
   réglementaires du secteur).
5. key_messages_by_persona : objet où chaque clé est une persona parmi
   ceo|cto_cio|ciso|business_director|purchasing|hr_talent|technical|operational
   (utilise uniquement les personas pertinentes vu context.contacts — pas les
   8 systématiquement), chaque valeur un tableau de 2-4 messages clés courts
   adaptés à cette persona.
6. objections : au moins 2 objections probables (prix, timing, concurrent interne,
   confiance...) avec une réponse courte et concrète à chacune. Appuie-toi sur
   context.pricingByPractice pour rester réaliste sur le sujet prix, SANS jamais
   citer un chiffre engageant (une fourchette indicative si nécessaire, jamais un
   TJM ferme — ce n'est pas une négociation).
7. Ne cite jamais une offre absente de context.offersCatalog.

FORMAT DE SORTIE — JSON valide UNIQUEMENT, sans backticks, structure EXACTE :
{
  "schema_version": 1,
  "offer_matches": [
    { "issue_id": "...", "offer_id": "...", "rationale": "...", "provenance": "relational|folio_legacy|inferred" }
  ],
  "approach_angles": ["...", "..."],
  "key_messages_by_persona": { "cto_cio": ["...", "..."] },
  "objections": [ { "objection": "...", "response": "..." } ]
}`;

const userPrompt = `CONTEXTE (source unique de vérité — JSON) :\n${JSON.stringify(context, null, 2)}`;

return [{
  json: {
    ...upstream,
    context,
    systemPrompt: SYSTEM_PROMPT,
    userPrompt,
  }
}];

