const response = $input.first().json;
const upstream = $('Assemble Prompt').item.json;
const textBlock = (response.content || []).find(b => b.type === 'text');
const content = textBlock && textBlock.text;

if (!content) {
  throw new Error('Le LLM a renvoyé un contenu vide');
}

let parsed;
try {
  const clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error('Réponse LLM non-JSON : ' + content.slice(0, 200));
}

if (parsed.schema_version !== 1) {
  throw new Error('schema_version doit valoir 1');
}
if (!Array.isArray(parsed.offer_matches)) {
  throw new Error('offer_matches manquant ou invalide');
}
if (!Array.isArray(parsed.approach_angles)) {
  throw new Error('approach_angles manquant ou invalide');
}
if (!parsed.key_messages_by_persona || typeof parsed.key_messages_by_persona !== 'object' || Array.isArray(parsed.key_messages_by_persona)) {
  throw new Error('key_messages_by_persona manquant ou invalide');
}
if (!Array.isArray(parsed.objections)) {
  throw new Error('objections manquant ou invalide');
}

const ALLOWED_PROVENANCE = new Set(['relational', 'folio_legacy', 'inferred']);
const issueIds = new Set((upstream.context.openIssues || []).map((i) => i.id));
const offerIds = new Set((upstream.context.offersCatalog || []).map((o) => o.id));

for (const match of parsed.offer_matches) {
  if (!issueIds.has(match.issue_id)) throw new Error(`issue_id inconnu dans offer_matches : ${match.issue_id}`);
  if (!offerIds.has(match.offer_id)) throw new Error(`offer_id inconnu dans offer_matches : ${match.offer_id}`);
  if (!match.rationale || typeof match.rationale !== 'string') throw new Error(`rationale manquant pour le match ${match.issue_id}/${match.offer_id}`);
  if (!ALLOWED_PROVENANCE.has(match.provenance)) throw new Error(`Provenance non autorisée : "${match.provenance}" (autorisé: relational, folio_legacy, inferred)`);
}

if (parsed.approach_angles.length < 2 || parsed.approach_angles.length > 4) {
  throw new Error(`approach_angles doit contenir 2 à 4 angles (reçu ${parsed.approach_angles.length})`);
}
for (const angle of parsed.approach_angles) {
  if (!angle || typeof angle !== 'string') throw new Error('Un angle d\'approche est vide ou invalide');
}

for (const [persona, messages] of Object.entries(parsed.key_messages_by_persona)) {
  if (!Array.isArray(messages) || messages.length === 0) throw new Error(`key_messages_by_persona.${persona} doit être un tableau non vide`);
  for (const m of messages) {
    if (!m || typeof m !== 'string') throw new Error(`Message clé invalide pour la persona ${persona}`);
  }
}

if (parsed.objections.length < 2) {
  throw new Error(`objections doit contenir au moins 2 entrées (reçu ${parsed.objections.length})`);
}
for (const obj of parsed.objections) {
  if (!obj.objection || typeof obj.objection !== 'string') throw new Error('Objection sans texte');
  if (!obj.response || typeof obj.response !== 'string') throw new Error(`Réponse manquante pour l'objection "${obj.objection}"`);
}

const strategy = {
  schema_version: 1,
  offer_matches: parsed.offer_matches,
  approach_angles: parsed.approach_angles,
  key_messages_by_persona: parsed.key_messages_by_persona,
  objections: parsed.objections,
  generated_at: new Date().toISOString(),
};

return [{
  json: {
    ...upstream,
    strategy,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

const data = $input.first().json;
const strategy = data.strategy;
const openIssues = data.context.openIssues || [];
const qaFlags = [];

qaFlags.push({ check: 'has_offer_matches', passed: strategy.offer_matches.length > 0 || openIssues.length === 0, detail: `${strategy.offer_matches.length} mapping(s) enjeu/offre` });

const coveredIssueIds = new Set(strategy.offer_matches.map((m) => m.issue_id));
const coverageRatio = openIssues.length > 0 ? coveredIssueIds.size / openIssues.length : 1;
qaFlags.push({
  check: 'issue_coverage',
  passed: coverageRatio >= 0.5,
  detail: `${coveredIssueIds.size}/${openIssues.length} enjeux ouverts couverts par au moins une offre`,
});

qaFlags.push({ check: 'angles_in_range', passed: strategy.approach_angles.length >= 2 && strategy.approach_angles.length <= 4, detail: `${strategy.approach_angles.length} angle(s) d'approche` });

qaFlags.push({ check: 'has_enough_objections', passed: strategy.objections.length >= 2, detail: `${strategy.objections.length} objection(s)` });

const personaCount = Object.keys(strategy.key_messages_by_persona).length;
qaFlags.push({ check: 'has_persona_messages', passed: personaCount > 0, detail: `${personaCount} persona(s) adressée(s)` });

return [{ json: { ...data, qaFlags } }];

const data = $input.first().json;
const companyName = (data.context.company && data.context.company.name) || 'Compte';

const sourceRefs = [
  { entityType: 'company', entityId: data.companyId, label: 'Fiche compte' },
];

const callbackBody = {
  runId: data.runId,
  phase: 1,
  resultType: 'commercial_strategy',
  status: 'succeeded',
  contentJson: data.strategy,
  contentText: [
    `# Stratégie commerciale — ${companyName}`,
    `## Angles d'approche`,
    ...data.strategy.approach_angles.map((a) => `- ${a}`),
    `## Mapping enjeu -> offre`,
    ...data.strategy.offer_matches.map((m) => `- Enjeu ${m.issue_id} -> Offre ${m.offer_id} : ${m.rationale}`),
  ].join('\n'),
  title: `Stratégie commerciale — ${companyName}`,
  modelProvider: 'anthropic',
  modelUsed: (data.llmUsage && data.llmUsage.model) || 'claude-sonnet-5',
  tokensInput: (data.llmUsage && data.llmUsage.inputTokens) || null,
  tokensOutput: (data.llmUsage && data.llmUsage.outputTokens) || null,
  contextSnapshot: data.context,
  sourceRefs,
  qaFlags: data.qaFlags || [],
};

return [{
  json: {
    callbackUrl: data.callbackUrl,
    rawBody: JSON.stringify(callbackBody),
  }
}];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;

try {
  const ve = $('Validate Entity').item.json;
  runId = ve.runId || null;
  callbackUrl = ve.callbackUrl || null;
} catch (e) {
  // Validate Entity n'a produit aucune sortie exploitable — notification impossible.
}

let errorMessage = 'Erreur inconnue dans le workflow intel-032-strategy';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

const callbackBody = {
  runId,
  phase: 1,
  resultType: 'commercial_strategy',
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{ json: { callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
